insert into "CozyCookBookSchema".folders (id, name, blurb, user_id, is_public, position) values
  ('89ad7cb7-e1f4-507f-8317-0047a027e635', 'South Indian', 'Fermented batters, tempered oil and coconut. Tiffin, rice plates and filter coffee.', null, true, 3072)
on conflict (id) do update set name = excluded.name, blurb = excluded.blurb;

insert into "CozyCookBookSchema".recipes
  (id, title, ingredients, steps, folder_id, user_id, meal, is_public, position)
select r.id, r.title,
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'name', n, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.ing) with ordinality as t(n, o)),
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'text', st, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.steps) with ordinality as t(st, o)),
  '89ad7cb7-e1f4-507f-8317-0047a027e635', null, r.meal, true, r.pos
from (values
  ('733fcdf5-a94f-5d5a-9afd-b0e2f0d65afb'::uuid, 'Plain Dosa', array['3 cups idli rice','1 cup urad dal','1 tsp fenugreek seeds','1/2 cup poha','Rock salt to taste','3 tbsp ghee'], array['Soak the rice and the dal separately, with the fenugreek in the dal, for six hours.','Grind the dal first to a light foam, then the rice to a fine grit.','Combine by hand — the warmth of your hands starts the ferment.','Ferment 8-12 hours until risen and sour-smelling.','Thin with water and spread on a hot tawa in one confident spiral.','Ghee round the edges; cook only one side.'], 'Breakfast', 0),
  ('516c1c68-85be-5ce7-8a4d-59f8e9796135'::uuid, 'Idli - Ajji''s Way', array['3 cups idli rice','1 cup urad dal','1/2 cup poha','1 tsp fenugreek seeds','Rock salt to taste','1 tbsp ghee'], array['Soak rice, dal, poha and fenugreek as for dosa but grind the batter thicker.','Ferment overnight somewhere warm until doubled.','Add rock salt only after fermenting — regular salt slows the culture.','Grease the plates with ghee and steam 12 minutes.','A skewer should come out clean and the idli should slide off the plate on its own.'], 'Breakfast', 1024),
  ('ad210bee-a2e8-5c80-b251-98d821b788f6'::uuid, 'Masala Dosa', array['1 batch dosa batter','4 russet potatoes, boiled','1 yellow onion, sliced','1 tsp mustard seeds','10 fresh curry leaves','2 green chilies, slit','1/2 tsp ground turmeric','3 tbsp oil','1/4 cup fresh cilantro'], array['Temper mustard seeds and curry leaves in oil until they pop.','Add onion, chilies and turmeric; soften without browning.','Fold in the crushed potato and cilantro. Keep it coarse.','Spread the dosa, place the filling on one half, and fold over.'], 'Breakfast', 2048),
  ('7868c03e-c0a2-5230-acb8-387085da692f'::uuid, 'Upma', array['1 cup semolina','1 yellow onion, diced','1 tsp mustard seeds','1 tbsp urad dal','10 fresh curry leaves','2 green chilies, slit','1 inch fresh ginger, minced','3 tbsp ghee','1 lemon'], array['Dry-roast the semolina until it smells nutty, then set aside.','Temper mustard seeds, urad dal and curry leaves in ghee.','Add onion, ginger and chilies and soften.','Add three cups of boiling water, then rain in the semolina while stirring hard.','Cover two minutes off the heat. Lemon at the end.'], 'Breakfast', 3072),
  ('44ecb4f0-644a-531d-99ca-be801ca4cce6'::uuid, 'Medu Vada', array['1 cup urad dal','2 green chilies, minced','1 inch fresh ginger, minced','10 fresh curry leaves','1 tsp black pepper, cracked','Salt to taste','Oil for frying'], array['Soak the dal four hours and grind with almost no water into a stiff fluffy batter.','Beat the batter by hand for five minutes — it should float in water.','Fold in chilies, ginger, curry leaves and pepper.','Wet your palm, flatten a ball, make a hole, and slide it into hot oil.','Fry until deep gold. Serve with sambar and chutney.'], 'Breakfast', 4096),
  ('4b8a9984-892f-5672-9974-3219cb7e4364'::uuid, 'Sambar', array['1 cup toor dal','1 tbsp tamarind paste','1 yellow onion, chunked','1 carrot, chunked','1 cup okra','2 tomatoes, chunked','3 tbsp sambar powder','1 tsp mustard seeds','10 fresh curry leaves','1/4 tsp asafoetida','3 tbsp oil'], array['Cook the toor dal until it collapses, then whisk it smooth.','Simmer the vegetables with tamarind and sambar powder until tender.','Combine with the dal and loosen with water to a pourable consistency.','Temper mustard seeds, curry leaves and asafoetida in hot oil and pour it in.','The tempering goes in at the very end, off the heat.'], 'Lunch', 5120),
  ('44f2197f-f42a-5c5c-a706-f160280235ec'::uuid, 'Rasam', array['1/2 cup toor dal','2 tbsp tamarind paste','3 tomatoes, crushed','2 tsp rasam powder','1 tsp cumin seeds','1 tsp black pepper','4 cloves garlic, crushed','10 fresh curry leaves','1/4 cup fresh cilantro','2 tbsp ghee'], array['Cook the dal soft and keep the thin liquid.','Simmer tamarind, tomato and rasam powder for 10 minutes until the raw smell goes.','Add the dal water and heat until it just froths — never let rasam boil hard.','Temper cumin, pepper, garlic and curry leaves in ghee and add.','Cilantro off the heat.'], 'Lunch', 6144),
  ('21d505d2-6f79-53cd-964f-43d3dcd3b290'::uuid, 'Lemon Rice', array['3 cups cooked rice, cooled','2 lemons, juiced','1 tsp mustard seeds','1 tbsp chana dal','2 tbsp peanuts','10 fresh curry leaves','2 dried red chilies','1/2 tsp ground turmeric','3 tbsp sesame oil'], array['Use cold, dry, day-old rice or it turns to paste.','Temper mustard seeds, dals, peanuts, chilies and curry leaves in sesame oil.','Add turmeric, then the rice, folding gently with a flat spoon.','Lemon juice off the heat so it stays bright.'], 'Lunch', 7168),
  ('b4f263dd-1a8a-541f-b2ac-308b58b554e6'::uuid, 'Curd Rice', array['3 cups cooked rice','2 cups yogurt','1/2 cup whole milk','1 tsp mustard seeds','10 fresh curry leaves','1 inch fresh ginger, minced','2 green chilies, slit','2 tbsp oil','1 pomegranate, seeded'], array['Mash the warm rice slightly with the back of a spoon.','Cool completely, then fold in the yogurt and milk.','Temper mustard seeds, curry leaves, ginger and chilies and stir through.','Pomegranate arils on top. Best on a hot day.'], 'Lunch', 8192),
  ('db2f4002-13d1-54a8-9b21-78b36444fe48'::uuid, 'Bisi Bele Bath', array['1 cup rice','1/2 cup toor dal','1 cup mixed vegetables','3 tbsp bisi bele bath powder','1 tbsp tamarind paste','1/4 cup cashews','4 tbsp ghee','1 tsp mustard seeds','10 fresh curry leaves'], array['Cook the rice and dal together until very soft — this dish is meant to be thick and sticky.','Cook the vegetables separately so they keep their shape.','Combine with tamarind and the spice powder and simmer, adding water freely.','Fry cashews in ghee with mustard seeds and curry leaves and pour over.'], 'Dinner', 9216),
  ('8f0ad351-ae29-50a4-9c48-2d07f6211ab7'::uuid, 'Chettinad Chicken', array['2 lbs chicken, bone-in','1 tbsp black pepper','1 tbsp coriander seeds','1 tsp cumin seeds','4 dried red chilies','1/4 cup fresh coconut, grated','2 yellow onions, sliced','1 tbsp ginger garlic paste','10 fresh curry leaves','3 tbsp sesame oil'], array['Dry-roast the pepper, coriander, cumin, chilies and coconut, then grind to a paste.','Brown the onions deeply in sesame oil.','Add ginger garlic paste and the ground masala; fry until it darkens and smells roasted.','Add the chicken and cook in its own moisture 30 minutes.','Curry leaves at the end.'], 'Dinner', 10240),
  ('8a341878-ab25-5cb4-84d6-6e9d827f5e13'::uuid, 'Kerala Fish Curry', array['2 lbs kingfish steaks','1 cup coconut milk','1 tbsp tamarind paste','2 tsp kashmiri chili powder','1/2 tsp ground turmeric','1 tsp fenugreek seeds','1 yellow onion, sliced','10 fresh curry leaves','1 inch fresh ginger, julienned','3 tbsp coconut oil'], array['Temper fenugreek and curry leaves in coconut oil.','Soften the onion and ginger, then add the ground spices and cook off the raw edge.','Add tamarind and a little water and simmer 10 minutes.','Slide in the fish and cook eight minutes without stirring — shake the pan instead.','Add coconut milk and warm through. Never boil it after this point.','It is better the next day.'], 'Dinner', 11264),
  ('8bd69098-0d34-5216-a8ea-de9df658fa55'::uuid, 'Avial', array['4 cups mixed vegetables, batons','1 cup fresh coconut, grated','2 green chilies','1 tsp cumin seeds','1 cup yogurt','10 fresh curry leaves','3 tbsp coconut oil','1/2 tsp ground turmeric'], array['Cook the vegetables with turmeric and very little water until just tender.','Grind coconut, chilies and cumin to a coarse paste.','Fold the paste in and cook two minutes.','Off the heat, stir in yogurt, raw coconut oil and curry leaves. The raw oil is the signature.'], 'Dinner', 12288),
  ('35fd7a5e-6ecc-50f7-9199-db7b35b862c5'::uuid, 'Vegetable Korma', array['4 cups mixed vegetables','1 cup coconut milk','1/4 cup cashews','2 green chilies','1 yellow onion, sliced','1 tbsp ginger garlic paste','1 tsp garam masala','10 fresh curry leaves','3 tbsp ghee','1/4 cup fresh cilantro'], array['Grind the cashews and chilies to a smooth paste.','Soften the onion in ghee without colouring, add ginger garlic paste.','Add the cashew paste and cook three minutes.','Add the vegetables and coconut milk and simmer until tender.','Cilantro and curry leaves at the end.'], 'Dinner', 13312),
  ('a4b6ad99-87fb-5099-be50-f559ba6fec96'::uuid, 'Coconut Chutney', array['1 cup fresh coconut, grated','2 tbsp roasted chana dal','2 green chilies','1 inch fresh ginger','1 tsp mustard seeds','10 fresh curry leaves','1 dried red chili','2 tbsp coconut oil','Salt to taste'], array['Grind coconut, chana dal, chilies and ginger with a little water.','Keep it slightly coarse.','Temper mustard seeds, curry leaves and the dried chili in coconut oil.','Pour the tempering over and do not stir it in until serving.'], 'Snack', 14336),
  ('a44c3f33-3d7d-598c-a4f2-6f3a0000b422'::uuid, 'Tomato Chutney', array['4 tomatoes, chopped','1 yellow onion, sliced','4 dried red chilies','1 tbsp chana dal','1 tbsp urad dal','1/4 tsp asafoetida','10 fresh curry leaves','3 tbsp sesame oil'], array['Fry the dals and chilies in oil until golden.','Add onion, then tomato, and cook down until jammy and the oil separates.','Cool and grind coarsely.','Temper curry leaves and asafoetida and stir through.'], 'Snack', 15360),
  ('dc172248-e782-5338-92d4-0897cb2e7f8d'::uuid, 'Vada Pav', array['4 russet potatoes, boiled','2 green chilies, minced','1 tsp mustard seeds','10 fresh curry leaves','1/2 tsp ground turmeric','1 cup chickpea flour','4 pav buns','Oil for frying','2 tbsp garlic chutney'], array['Temper mustard seeds and curry leaves, add chilies and turmeric, and fold into mashed potato.','Shape into balls and rest them.','Make a loose chickpea-flour batter, dip, and deep-fry until golden.','Split the pav, spread garlic chutney, and crush the vada inside.'], 'Snack', 16384),
  ('b3e4d858-4027-5bfe-b832-ff8753a9a38d'::uuid, 'Rava Kesari', array['1 cup semolina','1 cup granulated sugar','3 cups water','1/2 cup ghee','1 pinch saffron threads','4 green cardamom pods, ground','2 tbsp cashews','2 tbsp raisins'], array['Fry the cashews and raisins in ghee and set aside.','Roast the semolina in the same ghee until it smells nutty.','Add boiling saffron water carefully — it will spit — and stir until it thickens.','Add sugar; the mixture loosens, then tightens again. Keep going.','Finish with cardamom, the nuts, and more ghee than feels sensible.'], 'Snack', 17408),
  ('0c37e50d-30ad-5dcf-91db-c14032071f7c'::uuid, 'Payasam', array['1/2 cup vermicelli','4 cups whole milk','1/2 cup jaggery','3 tbsp ghee','2 tbsp cashews','2 tbsp raisins','4 green cardamom pods, ground'], array['Fry the vermicelli, cashews and raisins in ghee separately.','Simmer the vermicelli in the milk until soft.','Melt the jaggery in a little water, strain it, and add off the heat.','Adding jaggery to boiling milk will split it. Off the heat, always.'], 'Snack', 18432),
  ('c308ff5b-96b0-593f-8e5d-c2d6fe3d9f35'::uuid, 'Filter Coffee', array['4 tbsp coffee beans, ground fine','1 cup water, boiling','2 cups whole milk','3 tbsp granulated sugar'], array['Pack the grounds into the filter firmly but do not tamp them hard.','Pour boiling water over and let it drip for 20 minutes.','Boil the milk properly, not just warm it.','Mix decoction, milk and sugar, then pour between two tumblers from a height until it foams.'], 'Snack', 19456)
) as r(id, title, ing, steps, meal, pos)
on conflict (id) do update set title = excluded.title, ingredients = excluded.ingredients, steps = excluded.steps, meal = excluded.meal;
